    const attempts = deps.db.query('SELECT tx_hash,operation,outcome,observed_at FROM v2_order_attempts WHERE order_id=? ORDER BY observed_at, rowid').all(row.id) as any[]
    const status = await chain.getV2OrderStatus(accountAddress, row.digest)
    return { digest: row.digest, order: parseJson(row.order_json), action: parseJson(row.action_json), actionHash: row.action_hash, approvals: approvals.map(v => ({ signer: v.signer_address, createdAt: v.created_at })), attempts: attempts.map(v => ({ hash: v.tx_hash, operation: v.operation, outcome: v.outcome, observedAt: v.observed_at })), prepared: Boolean(row.prepared_data), openTransactionHash: row.open_tx_hash, closeTransactionHash: row.close_tx_hash, closeOperation: row.close_operation, status, createdAt: row.created_at, updatedAt: row.updated_at, venue: 'local_fixture_only' as const }
