  async function requireV2Actor(account: any, grant: { role: string; scopes: string[] }, auth: Auth, action: ActionIntent) {
    if (action.actor !== auth.address) throw new HttpError(403, 'NOT_AUTHORIZED', 'Only the action signer may prepare this order')
    if (grant.role === 'parent') { await requireCurrentParent(deps.chain, account, auth); return }
    if (grant.role !== 'caregiver' || (!grant.scopes.includes('*') && !grant.scopes.includes('trade.propose')) || !deps.chain.getDelegateAuthority)
      throw new HttpError(403, 'NOT_AUTHORIZED', 'A current caregiver grant is required')
    const authority = await deps.chain.getDelegateAuthority(account.address, auth.address)
    const mask = action.kind === 'BUY' ? 2n : 4n
    if (!authority.active || authority.securityEpoch !== account.security_epoch || (BigInt(authority.actionMask) & mask) === 0n)
      throw new HttpError(403, 'CHAIN_AUTHORITY_CHANGED', 'Caregiver trading authority is no longer active')
  }
